 const h=H.find(x=>x.ID===m[2]),tid=r['ID Task'],t=porId[tid],lista=r['ID lista']||listaId;
 const aplica=m[1]===kh&&h&&vigente(h,hoyH);
 if(!aplica){
  if(r.Estado==='Pendiente')setR(r,{Estado:m[1]===kh?'Omitido':'Sin marcar'});
  if(tid&&ok&&t&&!t.deleted)borrar.set(tid,{lista,id:tid});
  continue;
 }
 if(!tid)continue;
 // Conservar una cancelación/omisión local al recuperar, aunque Tasks esté tachada.
 if(!['Hecho','Pendiente'].includes(r.Estado)){if(ok&&t&&!t.deleted)borrar.set(tid,{lista,id:tid});continue;}
 if(ok&&t&&!t.deleted&&t.status==='completed'&&r.Estado!=='Hecho')setR(r,{Estado:'Hecho',Origen:'Google Tasks'});
 else if(ok&&t?.deleted&&r.Estado==='Pendiente')setR(r,{Estado:'No hecho',Origen:'Google Tasks'});
 else if(r.Estado==='Hecho'&&ok&&t&&!t.deleted&&t.status!=='completed'){
  const tu=DateTime.fromISO(String(t.updated||'')),rm=DateTime.fromFormat(String(r.Modificado||''),'yyyy-MM-dd H:mm',{zone:HZ});
  if(!recuperadas.has(r.ID)&&tu.isValid&&rm.isValid&&tu>rm.plus({minutes:1}))setR(r,{Estado:'Pendiente',Origen:'Google Tasks'});
  else completar.push({lista,id:tid});
 }
}
if(ok&&listaId)for(const h of H){
